// Command mellifera is the composition root: a flat, top-to-bottom
// constructor list wiring the whole app graph — no DI container, no
// reflection (ai-architecture §2; depguard denies both).
package main

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"sync"
	"syscall"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/art"
	"github.com/mellifera/mellifera/internal/browse"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/identity"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/pack"
	"github.com/mellifera/mellifera/internal/pairing"
	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/sourcestate"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
	"github.com/mellifera/mellifera/internal/watch"
	"github.com/mellifera/mellifera/internal/web"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// Launch-consent + identity constants shared with the plugin subprocess; the
// magic-cookie pair MUST match what every plugin validates, and coreVersion
// mirrors the plugins' min_core, or the handshake fails fatally.
const (
	magicCookieKey   = "MELLIFERA_MAGIC_COOKIE"
	magicCookieValue = "mellifera-plugin-v1"
	coreVersion      = "0.1.0"
	scannerService   = "mellifera.scanner.v1.Scanner"
	metadataService  = "mellifera.metadata.v1.MetadataSource"
)

// Lifecycle timeouts: a bounded read-header window (slowloris protection) and
// a best-effort graceful-shutdown budget (the plugin subprocess has its own
// SIGTERM grace, independent of this).
const (
	readHeaderTimeout = 10 * time.Second
	shutdownTimeout   = 15 * time.Second
)

func main() {
	cfg := loadConfig()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// --- wiring: flat constructor list, the whole app graph in order ---
	st, err := store.Open(ctx, cfg.dsn)
	fatalOn(err, "open store")
	defer st.Close()

	reg, err := module.Open(ctx, st)
	fatalOn(err, "open module registry")

	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   magicCookieKey,
		MagicCookieValue: magicCookieValue,
		CoreVersion:      coreVersion,
	})
	// sourceCatalog is the boot-literal plugin inventory (plugin-title-
	// enrichment D6): the single source for BOTH the pluginIDs set and the
	// Deps.SourceInventory closure.
	type catalogEntry struct {
		id, name, description string
	}
	sourceCatalog := []catalogEntry{
		{"base-scanner", "Base Scanner", "Directory scanner for tv and image libraries."},
		{"serial-scanner", "Serial Scanner", "Structure-aware directory scanner for serial libraries."},
		{"tv-parser", "TV Parser", "Local filename parser for tv episodes."},
		{"image-enricher", "Image Enricher", "Local EXIF metadata enrichment for images."},
		{"serial-parser", "Serial Parser", "Local directory-facts parser for serials."},
		{"frame-grabber", "Frame Grabber", "ffmpeg thumbnail and frame metadata for serial episodes."},
		{"shikimori", "Shikimori", "External Shikimori metadata enrichment for serials."},
		{module.PluginIDTmdb, "TMDB", "External TMDB metadata enrichment for tv and serial libraries."}, // {"tmdb", "TMDB" — 6.2 receipt anchor (design flag 8)
	}
	// pluginIDs derives from sourceCatalog so the load sites, the status
	// closure, and the admin-sources inventory cannot diverge.
	pluginIDs := make([]string, len(sourceCatalog))
	for i, p := range sourceCatalog {
		pluginIDs[i] = p.id
	}
	// loadedCaps is each loaded plugin's declared capability TYPES, captured
	// at its Load site — the Deps.PluginCapabilities validation set
	// (element-pages 3.1/3.3).
	loadedCaps := map[string][]string{}
	// loadPlugin is the flat per-plugin Load+Start pair, factored so
	// loadedCaps is captured at the declaration site (fail-fast kept).
	loadPlugin := func(pluginID, binaryPath string, caps []sdk.Capability) {
		fatalOn(mgr.Load(pluginID, binaryPath, caps), "load "+pluginID)
		fatalOn(mgr.Start(ctx, pluginID), "start "+pluginID)
		types := make([]string, 0, len(caps))
		for _, c := range caps {
			types = append(types, c.Type)
		}
		loadedCaps[pluginID] = types
	}

	// base-scanner is the tv/image scanner plugin.
	loadPlugin("base-scanner", cfg.baseScannerPath, []sdk.Capability{
		{Type: "scanner", ID: "default", ProtoService: scannerService},
	})

	// serial-scanner: directory-structured discovery, selected purely by
	// module config (serials-library D2).
	loadPlugin("serial-scanner", cfg.serialScannerPath, []sdk.Capability{
		{Type: "scanner", ID: "default", ProtoService: scannerService},
	})

	// tv-parser: the first metadata_source plugin (parseTV extracted from
	// base-scanner in T06/T07).
	loadPlugin("tv-parser", cfg.tvParserPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// image-enricher (EXIF via exiftool); started BEFORE the server serves
	// (INV-start-before-serve) so the first image scan's queue finds a live
	// enricher.
	loadPlugin("image-enricher", cfg.imageEnricherPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// serial-parser + frame-grabber: the serials-module metadata_source chain
	// (serials-library D3/D5).
	loadPlugin("serial-parser", cfg.serialParserPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})
	loadPlugin("frame-grabber", cfg.frameGrabberPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// shikimori: the first EXTERNAL metadata_source (serials-module chain's
	// priority-3 slot); fetches paced by the enrich FetchGate (enrichment D-5).
	loadPlugin("shikimori", cfg.shikimoriPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// tmdb: the second EXTERNAL metadata_source (tmdb-enrichment — tv-module
	// chain priority-3, serial seed v4 priority-4); its SERVER-mode api key
	// arrives through the binding's options JSON (D2), never an env var.
	loadPlugin(module.PluginIDTmdb, cfg.tmdbPath, []sdk.Capability{ // loadPlugin("tmdb" — 2.4 receipt anchor (design flag 8)
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	scanDeps := scan.Deps{
		Store:   st,
		Modules: reg,
		Plugins: mgr,
		// FetchGate (enrichment D-5 — box 2.2's injection point): the
		// per-plugin outbound pacing gate; nil would mean unpaced.
		Enrich: enrich.Deps{Store: st, Modules: reg, Plugins: mgr, FetchGate: enrich.NewFetchGate(),
			// RequiredSecrets (tmdb-enrichment D2/D4 — box 2.4's threading):
			// the plugin-declared secret NAMES; values resolve against the
			// binding's Options JSON, never through it.
			RequiredSecrets: mgr.RequiredSecrets,
			// Adopt (tombstone-lifecycle D4): the enrich settle fires identity
			// adoption — stranded progress/ledger re-keys onto the settled
			// item; never fails the settle (log-and-skip).
			Adopt: func(ctx context.Context, itemID string) {
				if err := scan.AdoptStranded(ctx, st, itemID); err != nil {
					slog.Warn("scan: identity adoption failed — skipped", "item", itemID, "error", err)
				}
			},
		},
	}

	// Packaged-playback pack lane (D-3/D-4/D-5): the enrich queue's PackItem
	// seam closes over the stream Service (Interface 2 — this closure is the
	// only bridge). The build-time gate is judged first
	// (playback-capability-gate D4 — the knob may flip between enqueue and
	// build): a closed verdict returns refusal.PolicyRefusal, Pack is never
	// called, and the pack_failed cooldown is never charged.
	mediaSvc := &stream.Service{
		Root:        cfg.streamsRoot,
		Secret:      cfg.mediaSecret,
		Original:    originalResolver(st),
		OptInCodecs: cfg.optInCodecs, // descriptor honesty shares the pack lane's knob
	}
	scanDeps.Enrich.PackItem = func(ctx context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (pack.PackOutcome, error) {
		// Job-start gate line (pack-manifest-audio D7): ONE "pack: gate" line
		// per pack job, before Pack; on a refusal the PolicyRefusal ends the
		// flow with no publish line (the persisted failed state is enrich's).
		logPackGate(itemID, ffprobe, stream.PackGate(ffprobe, mediaSvc.OptInCodecs))
		if err := packGateRefusal(ffprobe, mediaSvc.OptInCodecs); err != nil {
			return pack.PackOutcome{}, err
		}
		build, err := mediaSvc.Pack(ctx, itemID, absPath, ffprobe, voiceovers)
		return pack.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce, Codecs: build.Codecs, Layout: build.Layout}, err
	}
	// Client-relayed-fetch (D2/D4/D5): the enrich Relay, built BEFORE NewQueue
	// (which copies the Deps struct — a later assignment would miss the
	// queue's copy). The wake targets enrichQueue with the PROCESS ctx (the
	// scanDeps.Notify detachment); it only fires after Start assigns
	// enrichQueue.
	var enrichQueue *enrich.Queue
	enrichRelay := &enrich.Relay{
		Store:    st,
		LeaseTTL: relayLease(),
		Notify: func(_ context.Context, libraryID int64) {
			enrichQueue.Notify(ctx, libraryID)
		},
	}
	scanDeps.Enrich.Relay = enrichRelay
	// Async enrich queue (arch §4.4): started BEFORE the server serves so the
	// first scan's Notify lands in a running pool (INV-start-before-serve).
	enrichQueue = enrich.NewQueue(scanDeps.Enrich, cfg.enrich)
	fatalOn(enrichQueue.Start(ctx), "start enrich queue")

	// Browse index service (browse-scale D2/D4): the RAM read model over
	// newBrowseWiring's closures — built BEFORE the scan Notify closure and
	// api.New (INV2 — api never imports browse). Nothing runs here: the
	// janitor's boot pass warms it, its tick reconciles, the pokes ride the
	// wake channel.
	modulePres := newModulePresentationClosure(st, reg, loadedCaps)
	browseW := newBrowseWiring(st, reg, modulePres)
	browseSvc := browse.NewService(browseW.Deps)

	// scan hands the library to the queue after persisting items pending. The
	// closure substitutes the PROCESS ctx (not the per-request scan ctx) so the
	// queue's derive/feeder outlives the HTTP request — otherwise the feeder
	// would abort the moment the scan handler returns and never drain
	// (INV-context-shared: SIGINT/SIGTERM cancels pool + server together).
	// Scan-complete fan-out (browse-scale D4): rows and updated_at both moved,
	// so the poke runs the browse pass at once instead of waiting out the tick
	// (non-blocking, capacity-1 — a scan burst coalesces).
	scanDeps.Notify = func(_ context.Context, libraryID int64) {
		enrichQueue.Notify(ctx, libraryID)
		browseSvc.Wake()
	}
	// Deps.Status closure (arch §4.4 best-effort liveness; the INV2 seam built
	// HERE so api imports neither plugin nor enrich): pluginIDs →
	// api.PluginHealth, enrichQueue.Stats() → api.EnrichStats. A per-plugin
	// error omits that entry — never a 500 over one bad plugin.
	statusClosure := func(ctx context.Context) (api.AdminStatus, error) {
		plugins := make([]api.PluginHealth, 0, len(pluginIDs))
		for _, id := range pluginIDs {
			h, err := mgr.Status(id)
			if err != nil {
				slog.Warn("admin status: plugin status unavailable", "plugin", id, "error", err)
				continue
			}
			checkedAt := ""
			if !h.LastCheckedAt.IsZero() {
				checkedAt = h.LastCheckedAt.Format(time.RFC3339)
			}
			plugins = append(plugins, api.PluginHealth{
				ID:        id,
				State:     h.State,
				Message:   h.Message,
				Restarts:  h.Restarts,
				CheckedAt: checkedAt,
			})
		}
		es := enrichQueue.Stats()
		return api.AdminStatus{
			Plugins: plugins,
			Enrich: api.EnrichStats{
				Pending:  es.Pending,
				InFlight: es.InFlight,
				Done:     es.Done,
				Failed:   es.Failed,
			},
		}, nil
	}

	// sweeps is the per-library whole-sweep in-flight guard (enrichment design
	// Interfaces): process-lifetime by design — the guarded span is
	// synchronous inside Queue.ReenrichSource.
	sweeps := &sweepGuard{inFlight: map[int64]bool{}}

	// Device-pairing service (device-pairing D1): a nil Deps.Pairing seam
	// would 503 every pairing route in production.
	pairingSvc := pairing.NewService(st, time.Now)

	// Artwork service: the content-addressed blob tree over the store's art
	// tables; the api seam and the janitor's art task share its
	// in-process cooldown/pending state.
	artSvc := art.NewService(st, cfg.artRoot)

	// Accounts domain service (l6-accounts D9 — the Pairing precedent): the
	// composition root MUST assign it — api tolerates a nil Identity, but a
	// nil wiring would silently legacy-fall EVERY principal
	// (TestDepsIdentityWired pins the assignment).
	identitySvc := newIdentityService(st)

	// Eviction suppression set (eviction D3 — see suppressionSet): the sweeps
	// mark it, the frontier and integrity sweep consult it, the Deps.Play
	// closure clears it on a real play.
	suppress := newSuppressionSet()

	// The per-library scan single-flight (watch-scan D4): ONE instance shared
	// by BOTH trigger sources — a manual POST and a watcher fire join the same
	// in-flight run instead of stampeding the store.
	flight := newScanFlight()
	scanFn := func(ctx context.Context, libraryID int64) (scan.Result, error) {
		return scan.Run(ctx, scanDeps, libraryID)
	}

	apiHandler := api.New(api.Deps{
		AdminToken: cfg.adminToken,
		Store:      st,
		Pairing:    pairingSvc,
		Identity:   identitySvc,
		Art:        artSvc,
		Scan: func(ctx context.Context, libraryID int64) (scan.Result, error) {
			return flight.run(ctx, libraryID, scanFn)
		},
		Status: statusClosure,
		// Playback descriptor (D-7): pure delegation over the stream Service's
		// Describe + a fresh media token (INV2 — api never imports stream);
		// the decision log (tv-playback-unblock D8) rides the same closure.
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			return playbackDescriptor(ctx, st, mediaSvc, enrichQueue.EnqueuePack, cfg.optInCodecs, itemID)
		},
		// Play verb (D-7 — the ONLY playback mutation): retry rides the
		// PREFERRED lane (eviction D4: EnqueuePackUrgent; background dispatch
		// keeps the plain EnqueuePack); carries the eviction re-arm (eviction
		// D3 — see newPlayClosure).
		Play: newPlayClosure(st, enrichQueue.EnqueuePackUrgent, cfg.optInCodecs, suppress),
		// Watch-event seam, fanned out (continue-nextup-media D-1..D-4 +
		// recommendation-sorting D4): leg 1 the debounced thumbnail re-grab;
		// leg 2 the watch detector (idempotent watched_items insert at ≥ 90%)
		// + a recs wake. Both legs log-and-skip: progress is never load-bearing.
		OnProgress: fanOut(newThumbRegrab(st, mgr), newWatchDetect(st)),
		// Watch defaults (watch-flow-polish): the auto-next countdown seconds
		// served verbatim, floored at 1 — a non-positive knob can never make
		// auto-next an instant jump.
		WatchDefaults: autoNextCountdownSeconds(),
		// Module presentation (element-pages 3.4/3.1; plugin-title-enrichment
		// D5; l6-accounts 10.1): the ONE ResolveGates site under the REQUEST's
		// Viewer — every queue/scan/janitor site stays System.
		ModulePresentation: modulePres,
		// Admin sources aggregate (plugin-title-enrichment D6): the primitive
		// seams the api handler assembles its read-only inventory from — the
		// boot catalog above (INV2: api imports neither module nor enrich).
		SourceInventory: func(_ context.Context) ([]string, map[string]string, map[string]string) {
			ids := make([]string, len(sourceCatalog))
			names := make(map[string]string, len(sourceCatalog))
			descriptions := make(map[string]string, len(sourceCatalog))
			for i, p := range sourceCatalog {
				ids[i] = p.id
				names[p.id] = p.name
				descriptions[p.id] = p.description
			}
			return ids, names, descriptions
		},
		ModuleIDs: func(context.Context) ([]string, error) {
			mods, err := reg.List()
			if err != nil {
				return nil, err
			}
			ids := make([]string, 0, len(mods))
			for _, m := range mods {
				ids = append(ids, m.ID)
			}
			return ids, nil
		},
		ModuleSources: func(ctx context.Context, moduleID string, libraryID int64) ([]string, []int, []bool, error) {
			m, err := reg.Get(moduleID)
			if err != nil {
				return nil, nil, nil, err
			}
			libraryIDs := []int64(nil)
			if libraryID != 0 {
				libraryIDs = []int64{libraryID}
			}
			prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, libraryIDs)
			if err != nil {
				return nil, nil, nil, err
			}
			gated := enrich.ResolveGates(m, prefs, libraryID)
			pids := make([]string, 0, len(gated))
			priorities := make([]int, 0, len(gated))
			enabled := make([]bool, 0, len(gated))
			for _, src := range gated {
				pids = append(pids, src.PluginID)
				priorities = append(priorities, src.Priority)
				enabled = append(enabled, src.Enabled)
			}
			return pids, priorities, enabled, nil
		},
		// Parser-attachment validation (element-pages 3.3/3.1): answered from
		// loadedCaps — the validation set IS the loaded set (INV2).
		PluginCapabilities: func(_ context.Context, pluginID string) ([]string, bool) {
			caps, ok := loadedCaps[pluginID]
			return caps, ok
		},
		// Re-enrichment admin surface (enrichment D-6/D-7): built HERE so api
		// imports neither enrich nor plugin (INV2).
		Reenrich:      newReenrichClosure(ctx, st, reg, enrichQueue, loadedCaps, sweeps),
		EnrichPreview: newEnrichPreviewClosure(st, reg),
		// Identify overlay (identify-match-override): the interactive search
		// passthrough (live read on the request ctx) and the series re-anchor
		// (write detaches onto the process ctx). Same INV2 seam.
		SearchSource:   newSearchClosure(enrichQueue, reg, loadedCaps),
		IdentifySeries: newIdentifyClosure(ctx, reg, enrichQueue, loadedCaps),
		// Item identify (tmdb-enrichment): the same re-anchor seam over the
		// item row space — films are items.
		IdentifyItem: newItemIdentifyClosure(ctx, reg, enrichQueue, loadedCaps),
		// Plugin admin surfaces (plugin-admin-surfaces): the config-binding
		// flatten (options verbatim as raw JSON — INV4) and the log tail, both
		// keyed against loadedCaps for the unknown-plugin verdict.
		PluginConfigs: newPluginConfigsClosure(reg, loadedCaps),
		PluginLogs:    newPluginLogsClosure(mgr, loadedCaps),
		// Binding-options write (tmdb-enrichment 3.2, the plugin-admin delta):
		// the ONE module-config mutation the operator surface owns (INV2
		// seam).
		SetModuleBindingOptions: newModuleBindingOptionsClosure(reg),
		// Per-binding required-secrets verdicts (tmdb-enrichment 3.3):
		// Manager.RequiredSecrets' handshake declaration composed against THAT
		// module binding's options.
		RequiredSecretsStatus: newRequiredSecretsClosure(mgr, reg),
		// Parser wake (enrichment D-6): a parser attach/clear fires the queue's
		// Notify at once — PROCESS ctx substituted (the scanDeps.Notify
		// detachment).
		OnParsersChanged: func(_ context.Context, libraryID int64) {
			enrichQueue.Notify(ctx, libraryID)
		},
		// Source-gate wake (plugin-title-enrichment) + gate-flip fan-out
		// (browse-scale D4): a gate flip changes the composition chain with
		// zero row writes — poke at once, don't wait out the tick (Q4 ruled
		// the poke free). PROCESS ctx substituted (the scanDeps.Notify
		// detachment).
		OnSourceGateChanged: func(_ context.Context, libraryID int64) {
			enrichQueue.Notify(ctx, libraryID)
			browseSvc.Wake()
		},
		// Browse-scale serve closures (D3/D7 — the cmd-built seams api cannot
		// import browse for, INV2): ranked search hit ids, facet aggregates
		// projected to the parallel-slice wire, FacetIDs through the SAME
		// pass-built composer, and OnTitleChange poking the index (the poke
		// supplies the latency, the epoch the correctness).
		BrowseSearch: func(query string) ([]string, []string) {
			hits := browseSvc.Search(query)
			return hits.Series, hits.Items
		},
		LibraryFacets: func(libraryID int64) ([]string, [][]string, [][]int) {
			fs := browseSvc.Facets(strconv.FormatInt(libraryID, 10))
			keys := make([]string, len(fs))
			values := make([][]string, len(fs))
			counts := make([][]int, len(fs))
			for i, f := range fs {
				keys[i] = f.Key
				values[i] = make([]string, len(f.Values))
				counts[i] = make([]int, len(f.Values))
				for j, v := range f.Values {
					values[i][j] = v.Value
					counts[i][j] = v.Count
				}
			}
			return keys, values, counts
		},
		FacetIDs: browseW.FacetIDs,
		OnTitleChange: func(_ context.Context, _ string) {
			browseSvc.Wake()
		},
		// Client-relayed-fetch (D7): the two relay verbs as direct method
		// values, built HERE so api imports no enrich (INV2); RelayMaxBody is a
		// plain configured value — the composition root owns the env read.
		RelayClaim:   enrichRelay.Claim,
		RelayResult:  enrichRelay.Ingest,
		RelayMaxBody: relayMaxBody(),
	})

	// Packaged-playback orchestrator (D-8/D-9/D4): the watch-driven frontier +
	// budget eviction + integrity sweep — the janitor's streams task; the
	// budget knob is GiB (0 = off).
	sweep := newSweep(st, cfg.streamsRoot, mediaSvc.ValidateBuild, enrichQueue.EnqueuePack, int64(cfg.orchBudgetGB)<<30, cfg.optInCodecs, suppress)
	// artSettle is the registry's art task: ONE settle+GC pass per tick;
	// errors logged, never fatal — best-effort background work like the sweep.
	artSettle := func(ctx context.Context) {
		if err := artSvc.Settle(ctx); err != nil {
			slog.Warn("art: settle pass failed", "error", err)
		}
	}
	// The janitor registry (artwork D8): boot run of every enabled task
	// BEFORE serving, then per-task ticks.
	jan := newJanitor(
		janitorTask{name: "streams", interval: sweepInterval, fn: sweep},
		janitorTask{name: "art", interval: cfg.artInterval, fn: artSettle},
		// recs is the tag-affinity learning task (recommendation-sorting D5):
		// boot run + tick + the completion wake (notifyRecs, the watch
		// detector's write side).
		janitorTask{name: "recs", interval: recsInterval, wake: recsWake, fn: newRecsSweep(st, reg)},
		// browse is the search-index task (browse-scale D4): boot-warm is the
		// same Reconcile a tick runs; the wake's write side is browseSvc.Wake,
		// poked by the fan-outs above and api's OnTitleChange seam.
		janitorTask{
			name:     "browse",
			interval: browseInterval,
			wake:     browseSvc.WakeChan(),
			fn:       func(context.Context) { browseSvc.Reconcile() },
		},
	)
	// The watch-ledger backfill (recommendation-sorting follow-up), BEFORE the
	// boot pass: progress stock predating the watch detector reconciles into
	// watched_items in the same boot (log-and-skip).
	newRecsBackfill(st)(ctx)
	jan.runBoot(ctx)
	go jan.run(ctx)

	// The filesystem watcher (watch-scan D5): MELLIFERA_WATCH_INTERVAL ≤ 0 is
	// the off position ALONE — manual POST remains the only trigger. No boot
	// run: the first reconcile fires one interval after start.
	if wi := watchInterval(); wi > 0 {
		watchSvc := watch.NewService(watch.Deps{
			Libraries: func(ctx context.Context) ([]watch.Library, error) {
				rows, err := st.ListLibraries(ctx, access.System())
				if err != nil {
					return nil, err
				}
				libs := make([]watch.Library, len(rows))
				for i, row := range rows {
					libs[i] = watch.Library{ID: row.ID, RootPath: row.RootPath}
				}
				return libs, nil
			},
			// The watcher joins the SAME single-flight as the manual POST
			// (D4); the (scan.Result, err) pair collapses to the error the
			// watcher's trigger law wants (WARN, never fatal).
			Scan: func(ctx context.Context, libraryID int64) error {
				_, err := flight.run(ctx, libraryID, scanFn)
				return err
			},
		}, watch.Config{ReconcileInterval: wi, Debounce: watchDebounce()})
		go func() {
			if err := watchSvc.Run(ctx); err != nil {
				slog.Warn("watch: run loop exited; continuing with manual-only scanning", "error", err)
			}
		}()
	} else {
		slog.Info("watch: watcher disabled (MELLIFERA_WATCH_INTERVAL <= 0); manual POST /libraries/{id}/scan remains the only trigger")
	}

	// Single top-level http.Handler (INV-single-handler — no second
	// http.Server): the api router + the token-gated /media surface + the
	// embedded SPA + Swagger.
	handler := requestLog(web.Handler(apiHandler, web.Options{DevMode: cfg.webDev, Media: mediaSvc}))

	srv := &http.Server{
		Addr:              cfg.listenAddr,
		Handler:           handler,
		ReadHeaderTimeout: readHeaderTimeout,
	}

	serveErr := make(chan error, 1)
	go func() { serveErr <- srv.ListenAndServe() }()

	select {
	case <-ctx.Done():
		slog.Info("shutting down (signal received)")
	case err := <-serveErr:
		if !errors.Is(err, http.ErrServerClosed) {
			fatalOn(err, "http server") // unexpected early exit; store.Close runs via defer
		}
		return // server already closed cleanly
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	logErr(srv.Shutdown(shutdownCtx), "shutdown http server")
	// INV-shutdown-order: stop accepting HTTP, THEN the enrich pool, THEN the
	// plugin subprocesses — in-flight RPCs drain against still-live
	// subprocesses (best-effort within shutdownTimeout).
	enrichQueue.Stop()
	for _, id := range pluginIDs {
		logErr(mgr.Stop(shutdownCtx, id), "stop "+id)
	}
	// store.Close runs via the deferred st.Close() in main.
}

// config is the resolved startup configuration read from the environment.
type config struct {
	dsn               string
	streamsRoot       string
	artRoot           string
	artInterval       time.Duration
	mediaSecret       []byte
	orchBudgetGB      int
	optInCodecs       bool
	adminToken        string
	baseScannerPath   string
	serialScannerPath string
	tvParserPath      string
	imageEnricherPath string
	serialParserPath  string
	frameGrabberPath  string
	shikimoriPath     string
	tmdbPath          string
	listenAddr        string
	webDev            bool
	enrich            enrich.QueueConfig
}

// loadConfig reads configuration from the environment with sane defaults:
// fail-fast on the one hard requirement (an admin token), data dir ensured
// so the store can open its SQLite file underneath.
func loadConfig() config {
	dataDir := envOr("MELLIFERA_DATA_DIR", "./data")
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		fatal("create data dir", err)
	}
	adminToken := os.Getenv("MELLIFERA_ADMIN_TOKEN")
	if adminToken == "" {
		slog.Error("MELLIFERA_ADMIN_TOKEN is required; refusing to serve with an empty admin token")
		os.Exit(1)
	}
	return config{
		dsn: filepath.Join(dataDir, "mellifera.db"),
		// Packaged-playback: the artifact root inside the server's own data
		// space (never a library directory); an unset MELLIFERA_MEDIA_SECRET
		// falls back to a fresh random secret, never the admin credential
		// (D-6).
		streamsRoot: filepath.Join(dataDir, "streams"),
		mediaSecret: mediaSecret(),
		// Artwork: the content-addressed blob tree (again the server's own
		// data space); MELLIFERA_ART_INTERVAL=0 is the documented off position.
		artRoot:     filepath.Join(dataDir, "art"),
		artInterval: envDuration("MELLIFERA_ART_INTERVAL", 6*time.Hour),
		// Packaged-playback budget knob (D-9): GiB, default 32; 0 disables the
		// cap — the knob can never accidentally evict everything.
		orchBudgetGB: envInt("MELLIFERA_ORCH_BUDGET_GB", 32),
		// Opt-in codec knob (D-2's env surface, default off — the locked
		// default): false folds HEVC/AC-3 to direct_only, true makes them
		// packable.
		optInCodecs:       envBool("MELLIFERA_STREAM_OPT_IN_CODECS", false),
		adminToken:        adminToken,
		baseScannerPath:   envOr("MELLIFERA_BASE_SCANNER", "bin/base-scanner"),
		serialScannerPath: envOr("MELLIFERA_SERIAL_SCANNER", "bin/serial-scanner"),
		tvParserPath:      envOr("MELLIFERA_TV_PARSER", "bin/tv-parser"),
		imageEnricherPath: envOr("MELLIFERA_IMAGE_ENRICHER", "bin/image-enricher"),
		serialParserPath:  envOr("MELLIFERA_SERIAL_PARSER", "bin/serial-parser"),
		frameGrabberPath:  envOr("MELLIFERA_FRAME_GRABBER", "bin/frame-grabber"),
		shikimoriPath:     envOr("MELLIFERA_SHIKIMORI", "bin/shikimori"),
		tmdbPath:          envOr("MELLIFERA_TMDB", "bin/tmdb"),
		listenAddr:        envOr("MELLIFERA_LISTEN", "127.0.0.1:8080"),
		// webDev=true loosens the SPA cache headers so the Vite dev proxy can
		// hot-reload; default false (production: immutable /assets/*).
		webDev: envBool("MELLIFERA_WEB_DEV", false),
		// Async enrich queue knobs (arch §4.4): a missing/malformed value
		// falls back to the §4.4 default + warns (INV-env-defaults — startup
		// never aborts on an enrich knob).
		enrich: enrich.QueueConfig{
			Workers:       envInt("MELLIFERA_ENRICH_WORKERS", 4),
			MaxAttempts:   envInt("MELLIFERA_ENRICH_MAX_ATTEMPTS", 3),
			LeaseTTL:      envDuration("MELLIFERA_ENRICH_LEASE_TTL", 60*time.Second),
			Backoff:       envDuration("MELLIFERA_ENRICH_BACKOFF", 2*time.Second),
			ExhaustedCool: envDuration("MELLIFERA_ENRICH_EXHAUSTED_COOL", 7*24*time.Hour),
			NoDataCool:    envDuration("MELLIFERA_ENRICH_NODATA_COOL", 30*24*time.Hour),
			CoolCap:       envDuration("MELLIFERA_ENRICH_COOL_CAP", 365*24*time.Hour),
		},
	}
}

// envInt reads an integer env var, falling back to def (and logging a warning)
// when it is unset/empty/malformed. Used for the enrich knobs (INV-env-defaults).
func envInt(key string, def int) int {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		slog.Warn("invalid int env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return n
}

// autoNextCountdownSeconds resolves MELLIFERA_AUTO_NEXT_COUNTDOWN_SECONDS
// (default 10), floored at 1 — a non-positive knob must never make auto-next
// an instant jump.
func autoNextCountdownSeconds() int {
	return max(1, envInt("MELLIFERA_AUTO_NEXT_COUNTDOWN_SECONDS", 10))
}

// envDuration reads a duration env var (time.ParseDuration syntax), falling back
// to def (and logging a warning) when unset/empty/malformed (INV-env-defaults).
func envDuration(key string, def time.Duration) time.Duration {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	d, err := time.ParseDuration(v)
	if err != nil {
		slog.Warn("invalid duration env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return d
}

// watchInterval resolves MELLIFERA_WATCH_INTERVAL (default 1h), UNFLOORED —
// ≤ 0 is the watcher's off position (manual POST remains the only trigger).
func watchInterval() time.Duration {
	return envDuration("MELLIFERA_WATCH_INTERVAL", time.Hour)
}

// watchDebounce resolves MELLIFERA_WATCH_DEBOUNCE (default 30s), floored at
// 1s — a non-positive window must never fire one scan per event burst.
func watchDebounce() time.Duration {
	return max(time.Second, envDuration("MELLIFERA_WATCH_DEBOUNCE", 30*time.Second))
}

// relayLease resolves MELLIFERA_RELAY_LEASE (default 2m; a bare seconds
// integer is NOT accepted): how long one client owns a claimed relay job.
func relayLease() time.Duration {
	return envDuration("MELLIFERA_RELAY_LEASE", 2*time.Minute)
}

// relayMaxBody resolves MELLIFERA_RELAY_MAX_BODY (default 2 MiB, raw bytes):
// the handler's http.MaxBytesReader limit. Not clamped — a non-positive cap
// refuses every body with 413.
func relayMaxBody() int64 {
	return int64(envInt("MELLIFERA_RELAY_MAX_BODY", 2*1024*1024))
}

// envOr returns the named env var or def when it is unset/empty.
func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// mediaSecret resolves the media-token HMAC secret: MELLIFERA_MEDIA_SECRET
// (hex) when set, else a fresh random secret — tokens die at restart.
func mediaSecret() []byte {
	if v := os.Getenv("MELLIFERA_MEDIA_SECRET"); v != "" {
		b, err := hex.DecodeString(v)
		if err != nil || len(b) == 0 {
			fatal("parse MELLIFERA_MEDIA_SECRET", errors.New("must be non-empty hex"))
		}
		return b
	}
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		fatal("generate media secret", err)
	}
	return b
}

// copyStrings clones a string slice so a closure return can never alias its
// source — the registry's cached config state is copied defensively at the
// api seam.
func copyStrings(src []string) []string {
	out := make([]string, len(src))
	copy(out, src)
	return out
}

// originalResolver builds the stream Service's direct-floor resolver over
// the store: parsed.absolute_path; absent/unreadable → ok=false → 404.
func originalResolver(st *store.Store) func(ctx context.Context, itemID string) (string, bool) {
	return func(ctx context.Context, itemID string) (string, bool) {
		row, err := st.GetItem(ctx, itemID, access.System())
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return "", false
			}
			slog.Warn("media: original lookup failed", "item", itemID, "error", err)
			return "", false
		}
		var doc struct {
			Parsed struct {
				AbsolutePath string `json:"absolute_path"`
			} `json:"parsed"`
		}
		if err := json.Unmarshal(row.Document, &doc); err != nil {
			return "", false
		}
		return doc.Parsed.AbsolutePath, doc.Parsed.AbsolutePath != ""
	}
}

// sweepGuard is the per-library whole-sweep in-flight flag: a second
// concurrent whole-library sweep refuses with api.ErrRefreshInFlight (→ 409).
type sweepGuard struct {
	mu       sync.Mutex
	inFlight map[int64]bool
}

// begin claims the library's whole-sweep slot, reporting whether the claim
// succeeded (false = a sweep is already in flight).
func (g *sweepGuard) begin(libraryID int64) bool {
	g.mu.Lock()
	defer g.mu.Unlock()
	if g.inFlight[libraryID] {
		return false
	}
	g.inFlight[libraryID] = true
	return true
}

// finish releases the library's whole-sweep slot.
func (g *sweepGuard) finish(libraryID int64) {
	g.mu.Lock()
	defer g.mu.Unlock()
	delete(g.inFlight, libraryID)
}

// newIdentityService constructs the accounts domain service over the store
// (l6-accounts D9 — the pairing.NewService precedent).
func newIdentityService(st *store.Store) *identity.Service {
	return identity.NewService(st, time.Now)
}

// newModulePresentationClosure builds the api Deps.ModulePresentation seam
// (element-pages 3.4/3.1; widened per plugin-title-enrichment D5): the
// library-surface block + title-walk inputs over ONE batched prefs read
// resolved through enrich.ResolveGates (INV2 — api imports neither module
// nor enrich). The ONE ResolveGates site under the REQUEST's Viewer: its
// ChainMutes AND down post-ResolveGates on copies — mute-only, never revive;
// every other ResolveGates site stays System on purpose.
func newModulePresentationClosure(
	st *store.Store, reg *module.Registry, loadedCaps map[string][]string,
) func(context.Context, string, int64) (api.ModulePresentation, error) {
	return func(ctx context.Context, moduleID string, libraryID int64) (api.ModulePresentation, error) {
		m, err := reg.Get(moduleID)
		if err != nil {
			return api.ModulePresentation{}, err
		}
		parsers := make([]api.ParserBinding, 0, 1+len(m.MetadataSources))
		parsers = append(parsers, api.ParserBinding{
			ID:            m.Scanner.PluginID,
			Capability:    m.Scanner.CapabilityID,
			DisplayFields: copyStrings(m.Scanner.DisplayFields),
		})
		for _, src := range m.MetadataSources {
			parsers = append(parsers, api.ParserBinding{
				ID:            src.PluginID,
				Capability:    src.CapabilityID,
				DisplayFields: copyStrings(src.DisplayFields),
			})
		}
		prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, []int64{libraryID})
		if err != nil {
			return api.ModulePresentation{}, err
		}
		gated := enrich.ResolveGates(m, prefs, libraryID)
		// Chain-mute AND-down (l6-accounts D8/10.1): post-ResolveGates, on the
		// per-call copies ResolveGates returns; the zero Viewer is a no-op.
		viewer := access.FromContext(ctx)
		for i := range gated {
			if viewer.ChainMutes[gated[i].PluginID] {
				gated[i].Enabled = false
			}
		}
		byID := make(map[string]module.MetadataSourceBinding, len(gated))
		for _, src := range gated {
			byID[src.PluginID] = src
		}
		pres := api.ModulePresentation{
			IdentityFields: copyStrings(m.IdentityFields),
			Parsers:        parsers,
			// Module default element template (display-naming 3.3): the
			// composition floor under a library's naming_element_name option.
			ItemName:           m.ItemName,
			LanguagePreference: copyStrings(m.LanguagePreference),
		}
		for _, id := range m.TitleSourcePriority {
			src, ok := byID[id]
			if !ok {
				continue // a priority id with no modeled binding is config drift — skip it silently
			}
			pres.AddTitleSource(id, src.Enabled)
			// refresh_sources (plugin-admin-surfaces D1): the same walk
			// filtered to loaded + effectively enabled bindings — the refresh
			// pickers' option list; a muted source is never revived here.
			if _, loaded := loadedCaps[id]; loaded && src.Enabled {
				pres.AddRefreshSource(id, src.Enabled)
			}
		}
		// source_chain (media-data-convention D6, additive): every bound
		// metadata source in CHAIN order with its gate-resolved verdict —
		// a muted source rides WITH enabled=false (the api projection must
		// see the mute to skip the source). Not the filtered refresh walk.
		for _, src := range gated {
			pres.AddChainSource(src.PluginID, src.Enabled)
		}
		return pres, nil
	}
}

// newReenrichClosure builds the api Deps.Reenrich seam (enrichment design
// Interfaces): unknown-plugin/unknown-rows rejected with their api sentinels
// BEFORE any strip; a whole-library sweep claims the in-flight slot. procCtx
// is the PROCESS ctx (the scanDeps.Notify detachment).
func newReenrichClosure(
	procCtx context.Context, st *store.Store, reg *module.Registry, q *enrich.Queue,
	loadedPlugins map[string][]string, sweeps *sweepGuard,
) func(context.Context, int64, string, []string) (api.ReenrichResult, error) {
	return func(_ context.Context, libraryID int64, pluginID string, rowIDs []string) (api.ReenrichResult, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return api.ReenrichResult{}, fmt.Errorf("refresh %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		if len(rowIDs) == 0 { // whole-library sweep: one per library at a time
			if !sweeps.begin(libraryID) {
				return api.ReenrichResult{}, fmt.Errorf("library %d refresh %q: %w", libraryID, pluginID, api.ErrRefreshInFlight)
			}
			defer sweeps.finish(libraryID)
		} else {
			// Pre-check row identity so a 404 never strips anything (the
			// admin-API spec: unknown rows never trigger a strip).
			for _, id := range rowIDs {
				ok, err := rowInLibrary(procCtx, st, libraryID, id)
				if err != nil {
					return api.ReenrichResult{}, err
				}
				if !ok {
					return api.ReenrichResult{}, fmt.Errorf("refresh %q row %q: %w", pluginID, id, api.ErrUnknownRows)
				}
			}
		}
		// The request-scoped ctx is substituted with the PROCESS ctx — the
		// scanDeps.Notify detachment.
		stripped, deferred, err := q.ReenrichSource(procCtx, libraryID, pluginID, rowIDs...)
		if err != nil {
			return api.ReenrichResult{}, err
		}
		return api.ReenrichResult{Queued: stripped + deferred, Stripped: stripped, Deferred: deferred}, nil
	}
}

// rowInLibrary reports whether rowID names an item or series row of the
// library — row ids are opaque, so the library binding is the identity check.
func rowInLibrary(ctx context.Context, st *store.Store, libraryID int64, rowID string) (bool, error) {
	it, err := st.GetItem(ctx, rowID, access.System())
	switch {
	case err == nil:
		return it.LibraryID == libraryID, nil
	case !errors.Is(err, sql.ErrNoRows):
		return false, err
	}
	sr, err := st.GetSeries(ctx, rowID, access.System())
	switch {
	case err == nil:
		return sr.LibraryID == libraryID, nil
	case !errors.Is(err, sql.ErrNoRows):
		return false, err
	}
	return false, nil
}

// hasMetadataBinding reports whether any module config binds pluginID as a
// metadata_source — a scanner plugin is not refreshable.
func hasMetadataBinding(reg *module.Registry, pluginID string) bool {
	mods, err := reg.List()
	if err != nil {
		return false
	}
	for _, m := range mods {
		for _, src := range m.MetadataSources {
			if src.PluginID == pluginID {
				return true
			}
		}
	}
	return false
}

// newSearchClosure builds the api Deps.SearchSource seam (identify-match-
// override): a live read on the request ctx (a search notifies nothing);
// validation mirrors newReenrichClosure. The dormant-source sentinel
// (tmdb-enrichment D3 — INV2) re-wraps into the api-local twin (503).
func newSearchClosure(
	q *enrich.Queue, reg *module.Registry, loadedPlugins map[string][]string,
) func(context.Context, string, string, string) ([]map[string]any, error) {
	return func(ctx context.Context, pluginID, query, kind string) ([]map[string]any, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return nil, fmt.Errorf("search %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		cands, err := q.SearchSource(ctx, pluginID, query, kind)
		if errors.Is(err, sourcestate.ErrUnconfiguredSource) {
			return nil, fmt.Errorf("search %q: %w", pluginID, api.ErrUnconfiguredSource)
		}
		return cands, err
	}
}

// newIdentifyClosure builds the api Deps.IdentifySeries seam (identify-match-
// override): the picked anchor rides the PROCESS ctx (the scanDeps.Notify
// detachment); validation BEFORE any write; the dormant-source sentinel
// (tmdb-enrichment D3, INV2) → the api-local twin (503).
func newIdentifyClosure(
	procCtx context.Context, reg *module.Registry, q *enrich.Queue,
	loadedPlugins map[string][]string,
) func(context.Context, string, string, string) (bool, int, int, error) {
	return func(_ context.Context, seriesID, pluginID, externalID string) (bool, int, int, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return false, 0, 0, fmt.Errorf("identify %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		queued, stripped, deferred, err := q.IdentifySeries(procCtx, seriesID, pluginID, externalID)
		if errors.Is(err, sourcestate.ErrUnconfiguredSource) {
			return false, 0, 0, fmt.Errorf("identify %q: %w", pluginID, api.ErrUnconfiguredSource)
		}
		return queued, stripped, deferred, err
	}
}

// newItemIdentifyClosure builds the api Deps.IdentifyItem seam (tmdb-
// enrichment): the series re-anchor generalized over any row (films are
// items) — same detachment/validation/translation as newIdentifyClosure.
func newItemIdentifyClosure(
	procCtx context.Context, reg *module.Registry, q *enrich.Queue,
	loadedPlugins map[string][]string,
) func(context.Context, string, string, string) (bool, int, int, error) {
	return func(_ context.Context, itemID, pluginID, externalID string) (bool, int, int, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return false, 0, 0, fmt.Errorf("identify %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		queued, stripped, deferred, err := q.IdentifyItem(procCtx, itemID, pluginID, externalID)
		if errors.Is(err, sourcestate.ErrUnconfiguredSource) {
			return false, 0, 0, fmt.Errorf("identify %q: %w", pluginID, api.ErrUnconfiguredSource)
		}
		return queued, stripped, deferred, err
	}
}

// previewBatch is the pagination width for the preview closure's QueryItems
// scan (the queue's deriveBatch width).
const previewBatch = 1000

// newEnrichPreviewClosure builds the api Deps.EnrichPreview seam (enrichment
// D-7): the per-plugin drift picture — matches, pending, cooling, version
// histogram — computed on demand; its predicates mirror the queue's
// pendingSources + inCooldown semantics, so consented numbers are acted-on
// numbers.
func newEnrichPreviewClosure(st *store.Store, reg *module.Registry) func(context.Context, int64, string) (api.EnrichPreview, error) {
	return func(ctx context.Context, libraryID int64, pluginID string) (api.EnrichPreview, error) {
		failures, err := st.ListFailures(ctx)
		if err != nil {
			return api.EnrichPreview{}, fmt.Errorf("preview: list ledger: %w", err)
		}
		nowt := time.Now()
		cooling := make(map[string]bool)
		for _, fr := range failures {
			if fr.PluginID == pluginID && fr.NextEligibleAt.After(nowt) {
				cooling[fr.ItemID] = true
			}
		}
		pv := api.EnrichPreview{PluginID: pluginID, Versions: map[string]int{}}
		account := func(rowID, moduleID string, docRaw json.RawMessage) {
			var doc map[string]any
			if err := json.Unmarshal(docRaw, &doc); err != nil {
				return // soft: an unreadable document contributes nothing (decodeDoc's rule)
			}
			namespaced := hasSourceNamespace(doc, pluginID)
			if namespaced {
				pv.Matches++
			}
			if queueableBinding(reg, moduleID, pluginID) && !namespaced && !cooling[rowID] {
				pv.Pending++
			}
			prov, ok := doc["_provenance"].(map[string]any)
			if !ok {
				return
			}
			for _, entry := range prov {
				e, ok := entry.(map[string]any)
				if !ok {
					continue
				}
				if pid, _ := e["plugin_id"].(string); pid == pluginID {
					v, _ := e["plugin_version"].(string)
					pv.Versions[v]++
				}
			}
		}
		for offset := 0; ; offset += previewBatch {
			batch, err := st.QueryItems(ctx, libraryID, "", "", false, previewBatch, offset, access.System())
			if err != nil {
				return api.EnrichPreview{}, fmt.Errorf("preview: query items lib %d: %w", libraryID, err)
			}
			for _, it := range batch {
				account(it.ID, it.ModuleID, it.Document)
			}
			if len(batch) < previewBatch {
				break
			}
		}
		seriesRows, err := st.QuerySeries(ctx, libraryID, "", access.System())
		if err != nil {
			return api.EnrichPreview{}, fmt.Errorf("preview: query series lib %d: %w", libraryID, err)
		}
		for _, sr := range seriesRows {
			account(sr.ID, sr.ModuleID, sr.Document)
		}
		return pv, nil
	}
}

// hasSourceNamespace reports whether the document carries the plugin's
// sources.<pluginID> namespace (the enrich chain's shape, restated cmd-side).
func hasSourceNamespace(doc map[string]any, pluginID string) bool {
	sources, ok := doc["sources"].(map[string]any)
	if !ok {
		return false
	}
	_, exists := sources[pluginID]
	return exists
}

// queueableBinding reports whether moduleID's config binds pluginID as a
// RUNNABLE metadata source — the queue's D-Q1 predicate restated cmd-side.
func queueableBinding(reg *module.Registry, moduleID, pluginID string) bool {
	mod, err := reg.Get(moduleID)
	if err != nil {
		return false
	}
	for _, src := range mod.MetadataSources {
		if src.PluginID == pluginID {
			return src.Enabled && src.AuthMode != "CLIENT"
		}
	}
	return false
}

// Binding-kind literals of the plugin-config rows (plugin-admin-surfaces):
// restated because the wire DTOs are api-unexported (INV4 keeps them from
// sharing a type).
const (
	bindingKindScanner  = "scanner"
	bindingKindMetadata = "metadata"
)

// pluginConfigRows accumulates one plugin's binding rows as parallel slices —
// the primitive return shape the api export budget forces.
type pluginConfigRows struct {
	moduleIDs, kinds, authModes, displayFields, options []string
	priorities                                          []int
	enabled                                             []bool
}

func (r *pluginConfigRows) add(moduleID, kind string, priority int, enabled bool, authMode, displayFields, options string) {
	r.moduleIDs = append(r.moduleIDs, moduleID)
	r.kinds = append(r.kinds, kind)
	r.priorities = append(r.priorities, priority)
	r.enabled = append(r.enabled, enabled)
	r.authModes = append(r.authModes, authMode)
	r.displayFields = append(r.displayFields, displayFields)
	r.options = append(r.options, options)
}

// newPluginConfigsClosure builds the api Deps.PluginConfigs seam
// (plugin-admin-surfaces D4): one row per module binding; options ride as RAW
// JSON (INV4). An id outside loadedPlugins is unknown.
func newPluginConfigsClosure(reg *module.Registry, loadedPlugins map[string][]string) func(context.Context, string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
	return func(_ context.Context, pluginID string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded {
			return nil, nil, nil, nil, nil, nil, nil,
				fmt.Errorf("plugin configs %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		mods, err := reg.List()
		if err != nil {
			return nil, nil, nil, nil, nil, nil, nil, err
		}
		rows := &pluginConfigRows{}
		for _, m := range mods {
			if m.Scanner.PluginID == pluginID {
				rows.add(m.ID, bindingKindScanner, 0, false, "", "",
					string(m.Scanner.Options))
			}
			for _, src := range m.MetadataSources {
				if src.PluginID != pluginID {
					continue
				}
				rows.add(m.ID, bindingKindMetadata, src.Priority, src.Enabled,
					src.AuthMode, rawStringsJSON(src.DisplayFields), string(src.Options))
			}
		}
		return rows.moduleIDs, rows.kinds, rows.priorities, rows.enabled,
			rows.authModes, rows.displayFields, rows.options, nil
	}
}

// rawStringsJSON flattens display_fields to a raw JSON string; undeclared
// fields ride as "" (omitted on the wire).
func rawStringsJSON(fields []string) string {
	if len(fields) == 0 {
		return ""
	}
	b, err := json.Marshal(fields)
	if err != nil {
		return ""
	}
	return string(b)
}

// newPluginLogsClosure builds the api Deps.PluginLogs seam (plugin-admin-
// surfaces D3): pure delegation over Manager.Logs.
func newPluginLogsClosure(mgr *plugin.Manager, loadedPlugins map[string][]string) func(context.Context, string) ([]string, error) {
	return func(_ context.Context, pluginID string) ([]string, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded {
			return nil, fmt.Errorf("plugin logs %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		lines, err := mgr.Logs(pluginID)
		if err != nil {
			return nil, fmt.Errorf("plugin logs %q: %w", pluginID, err)
		}
		return lines, nil
	}
}

// newModuleBindingOptionsClosure builds the api Deps.SetModuleBindingOptions
// seam (tmdb-enrichment 3.2): Registry.SetBindingOptions on the request ctx;
// the registry's refusal sentinels are unexported, so classification happens
// here — before any write.
func newModuleBindingOptionsClosure(reg *module.Registry) func(context.Context, string, string, json.RawMessage) error {
	return func(ctx context.Context, moduleID, pluginID string, options json.RawMessage) error {
		m, err := reg.Get(moduleID)
		if err != nil {
			return fmt.Errorf("module options %q: %w", moduleID, sourcestate.ErrUnknownModule)
		}
		for _, src := range m.MetadataSources {
			if src.PluginID == pluginID {
				return reg.SetBindingOptions(ctx, moduleID, pluginID, options)
			}
		}
		return fmt.Errorf("module options %q source %q: %w", moduleID, pluginID, api.ErrUnknownPlugin)
	}
}

// newRequiredSecretsClosure builds the api Deps.RequiredSecretsStatus seam
// (tmdb-enrichment 3.3): a declared name is provided iff its key exists in
// THAT binding's Options JSON (presence, never non-emptiness).
func newRequiredSecretsClosure(mgr *plugin.Manager, reg *module.Registry) func(moduleID, pluginID string) map[string]bool {
	return func(moduleID, pluginID string) map[string]bool {
		names := mgr.RequiredSecrets(pluginID)
		if len(names) == 0 {
			return nil
		}
		var options json.RawMessage
		if m, err := reg.Get(moduleID); err == nil {
			for _, src := range m.MetadataSources {
				if src.PluginID == pluginID {
					options = src.Options
					break
				}
			}
		}
		var opts map[string]string
		if len(options) > 0 {
			_ = json.Unmarshal(options, &opts)
		}
		out := make(map[string]bool, len(names))
		for _, name := range names {
			_, provided := opts[name]
			out[name] = provided
		}
		return out
	}
}

// envBool reads a boolean env var, falling back on unset/empty/invalid
// (INV-env-defaults: startup never aborts on a knob).
func envBool(key string, def bool) bool {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	b, err := strconv.ParseBool(v)
	if err != nil {
		slog.Warn("invalid bool env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return b
}

// fatalOn aborts the process if err is non-nil. Used for startup wiring, where a
// failure means the app cannot run.
func fatalOn(err error, label string) {
	if err != nil {
		fatal(label, err)
	}
}

func fatal(label string, err error) {
	slog.Error(label, "error", err)
	os.Exit(1)
}

// logErr logs a non-nil error without aborting. Used in the graceful-shutdown
// path so each step gets a chance to run even if an earlier one errored.
func logErr(err error, label string) {
	if err != nil {
		slog.Error(label, "error", err)
	}
}
